params.query:
# radar-backtest cordis_sparql dataset=projects page
PREFIX eurio: <http://data.europa.eu/s66#>
SELECT ?project_id ?acronym (STR(?sd) AS ?start_date) (STR(?sig) AS ?signature_date) (REPLACE(STR(?grant), "^.*/", "") AS ?grant_uuid)
WHERE {
  ?project a eurio:Project ; eurio:identifier ?project_id .
  OPTIONAL { ?project eurio:hasAcronym ?acr . ?acr eurio:shortForm ?acronym }
  OPTIONAL { ?project eurio:startDate ?sd }
  OPTIONAL { ?project eurio:signatureDate ?sig }
  OPTIONAL { ?project eurio:isFundedBy ?grant }
}
ORDER BY ?project_id ?acronym ?sd ?sig ?grant
LIMIT 10000 OFFSET 40000
